  ["Tu ruta de %s usaba %s, que este instructor no enseña: se calcula otra desde tu nivel."] = "Votre parcours de %s utilisait %s, que ce maître n'enseigne pas : un nouveau parcours est calculé depuis votre niveau.",
  ["Tu ruta de %s ya no se puede seguir con lo que enseña este instructor: se calcula otra desde tu nivel."] = "Votre parcours de %s ne peut plus être suivi avec ce qu'enseigne ce maître : un nouveau parcours est calculé depuis votre niveau.",
  ["No puedes aprender %s: ya tienes dos profesiones principales. Olvida una primero (desde su ventana de profesión)."] = "Vous ne pouvez pas apprendre %s : vous avez déjà deux métiers principaux. Désapprenez-en un d'abord (depuis sa fenêtre de métier).",
  ["Vender al vendedor"] = "Vendre au marchand",
