  ["Estancado: %s (%d de %d seguían en el siguiente escaneo)"] = "Bloqué : %s (%d sur %d étaient encore là à l'analyse suivante)",
  ["Estancado: faltan escaneos (bastan 1-2 al día durante un par de días)"] = "Bloqué : il faut plus d'analyses (1-2 par jour pendant quelques jours)",
  ["Precio clavado: el mínimo lleva %s sin moverse y hay %d subastas en él"] = "Prix plancher : le minimum n'a pas bougé depuis %s et %d enchères sont à ce prix",
  ["Precio clavado: no, el mínimo lleva %s quieto pero hay pocas subastas en él"] = "Prix plancher : non, le minimum n'a pas bougé depuis %s mais peu d'enchères sont à ce prix",
  ["Precio clavado: no, el mínimo se ha movido en el último día"] = "Prix plancher : non, le minimum a bougé au cours du dernier jour",
  ["Precio clavado: falta historial de al menos medio día"] = "Prix plancher : il faut au moins une demi-journée d'historique",
  ["Más oferta: de %d a %d uds a la venta en %s (%+d%%)"] = "Plus d'offre : de %d à %d en vente en %s (%+d%%)",
  ["Más oferta: falta una foto de hace ~1 día"] = "Plus d'offre : il faut un relevé d'il y a ~1 jour",
