  [" (%d de %d señales en contra)"] = " (%d signaux d'alerte sur %d)",
  ["Las más baratas no se venden: aunque el margen parezca bueno, probablemente no lo venderás."] = "Les moins chères ne se vendent pas : même si la marge semble bonne, vous ne le vendrez probablement pas.",
  ["Precio clavado y cada vez más oferta: aunque el margen parezca bueno, probablemente no lo venderás."] = "Prix plancher et offre en hausse : même si la marge semble bonne, vous ne le vendrez probablement pas.",

  -- ProfessionUI
  ["objeto "] = "objet",
  ["no quedan suficientes en la AH de: "] = "pas assez restant à l'HV de :",
  ["%d materiales sin precio (no están en la AH)"] = "%d composants sans prix (pas à l'HV)",
  ["%d materiales sin precio: aún no tienes escaneo de la Casa de Subastas. Ábrela y pulsa Escanear"] = "%d composants sans prix : vous n'avez pas encore d'analyse de l'hôtel des ventes. Ouvrez-le et cliquez sur Analyser",
  ["Casa de Subastas neutral"] = "Hôtel des ventes neutre",
  ["Crafter's Journal aún no funciona en la Casa de Subastas neutral. Aquí no escanea ni abre sus ventanas; tus rutas y precios siguen siendo los de la Casa de Subastas de tu facción."] = "Crafter's Journal ne fonctionne pas encore à l'hôtel des ventes neutre. Il n'analyse pas ici et n'ouvre pas ses fenêtres ; vos parcours et vos prix restent ceux de l'hôtel des ventes de votre faction.",
  ["Aviso en la Casa de Subastas neutral"] = "Avertissement à l'hôtel des ventes neutre",
  ["Al abrir la Casa de Subastas neutral (Bahía del Botín, Gadgetzan, Vista Eterna), una ventana avisa de que Crafter's Journal aún no funciona en ella."] = "À l'ouverture de l'hôtel des ventes neutre (Baie-du-Butin, Gadgetzan, Long-guet), une fenêtre indique que Crafter's Journal n'y fonctionne pas encore.",
  ["no hay más recetas de instructor para ese nivel"] = "plus de recettes de maître pour ce niveau",
  ["lo que sigue se aprende de pergaminos que no vende ningún vendedor ni están en la AH: %s"] = "la suite s'apprend avec des recettes qu'aucun marchand ne vend et qui ne sont pas à l'HV : %s",
  ["lo que sigue pide más reputación: %s"] = "la suite demande plus de réputation : %s",
  ["lo que sigue es de una especialización que no tienes: %s"] = "la suite relève d'une spécialisation que vous n'avez pas : %s",
  ["lo que sigue se compra con Merchant's Favor (actívalo con su icono): %s"] = "la suite s'achète avec Merchant's Favor (activez-le avec son icône) : %s",
  ["Amarilla desde %d · verde desde %d · gris desde %d"] = "Jaune dès %d · vert dès %d · gris dès %d",
  ["Hay recetas con más probabilidad, pero falta el precio de algún material en la AH:"] = "Il existe des recettes avec de meilleures chances, mais un composant n'a pas de prix à l'HV :",
  [": falta "] = " : manque",
  ["Si consigues esos materiales (o aparecen en la AH), el plan las usará."] = "Si vous obtenez ces composants (ou s'ils apparaissent à l'HV), le plan les utilisera.",
  ["No hay ninguna receta de instructor mejor en este tramo: esta es la única opción."] = "Il n'y a pas de meilleure recette de maître dans cette tranche : c'est la seule option.",
  ["Materiales de este paso:"] = "Composants pour cette étape :",
  ["Probabilidad de subir: del %d%% al %d%%"] = "Chance de monter : de %d%% à %d%%",
  ["fabricarlo (%s): %s/u · comprarlo hecho: %s/u"] = "le fabriquer (%s) : %s/u · l'acheter tout fait : %s/u",
  ["comprado: %s/u · fabricarlo (%s): %s/u"] = "acheté : %s/u · le fabriquer (%s) : %s/u",
  ["fabricarlo quitaría puntos a %s"] = "le fabriquer prendrait des points à %s",
  ["Guarda %d para pasos posteriores."] = "Gardez-en %d pour les étapes suivantes.",
  ["Vendido al vendedor recuperas %s por fabricación."] = "Vendu au marchand, vous récupérez %s par fabrication.",
  ["Lenta: %s por fabricación."] = "Lente : %s par fabrication.",
  ["Si prefieres otra receta, quítala con la X (o activa \"Menos fabricaciones\", que evita las lentas)."] = "Si vous préférez une autre recette, retirez-la avec le X (ou activez « Moins de fabrications », qui évite les lentes).",
  ["Si lo vendes en la AH podrías sacar hasta %s más en este paso, pero no se sabe cuántos se venden."] = "Vendre à l'HV pourrait rapporter jusqu'à %s de plus à cette étape, mais personne ne sait combien se vendent.",
  ["Precio poco fiable: "] = "Prix peu fiable :",
  ["Fabricas %d en total en el plan."] = "Vous en créez %d au total dans le plan.",
  ["Guarda %d (no los vendas):"] = "Gardez-en %d (ne les vendez pas) :",
  [" (paso %d-%d)"] = " (étape %d-%d)",
  ["  %dx para %s%s"] = "  %dx pour %s%s",
  ["Te sobran %d. El plan cuenta venderlos al vendedor a %s cada uno."] = "Il en reste %d. Le plan compte leur vente au marchand à %s pièce.",
  ["En la AH te quedarían %s cada uno igualando a la más barata (subasta de 24 h, comisión y depósito de %s descontados): hasta %s más en total."] = "À l'HV vous obtiendriez %s pièce au prix le plus bas (enchère de 24 h, commission et %s de dépôt déduits) : jusqu'à %s de plus au total.",
  ["Pero el juego no dice cuántos se venden: puede que no los vendas todos, o ninguno. Anuncia unos pocos y mira las alertas:"] = "Mais le jeu ne dit pas combien se vendent : peut-être pas tous, ou aucun. Mettez-en quelques-uns en vente et surveillez les alertes :",
  ["Consejo: pon los %d en la AH a %s (1 cobre menos que la más barata)."] = "Conseil : mettez les %d en vente à l'HV à %s (1 cuivre sous le moins cher).",
  ["Consejo: pon solo %d en la AH a %s para probar y vende el resto al vendedor; si se venden, anuncia más."] = "Conseil : mettez seulement %d en vente à l'HV à %s pour tester et vendez le reste au marchand ; s'ils se vendent, mettez-en plus.",
  ["Consejo: con estas alertas, mejor véndelos al vendedor."] = "Conseil : avec ces alertes, mieux vaut les vendre au marchand.",
  ["Consejo: véndelos al vendedor; en la AH no compensa la diferencia."] = "Conseil : vendez-les au marchand ; l'écart avec l'HV n'en vaut pas la peine.",
  ["%d uds a %s de media, comprando de la más barata a la más cara (ahora hay %d a la venta)."] = "%d à %s en moyenne, en achetant du moins cher au plus cher (%d en vente actuellement).",
