  ["Peor porque: "] = "Moins bien car :",
  ["Vendiendo lo fabricado en la AH saldría %s mejor que la ruta, si se vende (la ruta cuenta el vendedor, que es lo seguro)."] = "Vendre ce qui est créé à l'HV rapporterait %s de plus que le parcours, si ça se vend (le parcours compte le marchand, qui est sûr).",
  -- Calculadora
  ["Calculadora"] = "Calculatrice",
  ["Cuánto ganas con una receta, como en una hoja de cálculo: guarda varios cálculos y escribe tus precios."] = "Combien une recette vous rapporte, comme un tableur : enregistrez plusieurs calculs et saisissez vos propres prix.",
  ["Cuánto ganas con una receta: materiales en crudo, venta, comisión y depósito. Escribe tus precios si la AH ha cambiado."] = "Combien une recette vous rapporte : composants bruts, vente, commission et dépôt de l'HV. Saisissez vos propres prix si l'HV a changé.",
  ["Receta desconocida"] = "Recette inconnue",
