  ["vendedor"] = "marchand",
  ["Subasta de %d h"] = "enchère de %d h",
  ["Depósito: el %d%% del precio de vendedor, mínimo %s por subasta. Se devuelve si se vende; lo pierdes si caduca o la cancelas."] = "Dépôt : %d%% du prix marchand, au moins %s par enchère. Rendu si ça se vend ; perdu si elle expire ou si vous l'annulez.",
  ["sin precio"] = "pas de prix",
