  ["No fabrica un objeto que se pueda vender (encantamiento)."] = "Elle ne crée pas d'objet vendable (enchantement).",
  ["Comisión de la AH (%d%%)"] = "Commission de l'HV (%d%%)",
  ["Chat de comercio"] = "Canal commerce",
  ["Vender por el chat de comercio"] = "Vendre par le canal commerce",
  ["Al precio que paga el vendedor: venta segura, sin comisión ni depósito."] = "Au prix que paie le marchand : une vente sûre, sans commission ni dépôt.",
  ["Beneficio vendiendo al vendedor (sin AH)"] = "Bénéfice en vendant au marchand (sans HV)",
