  ["Vendidos %d objetos al vendedor."] = "%d objets vendus au marchand.",
  ["Vende al vendedor todo lo que va al vendedor (no lo que va a la AH ni lo que guardan tus rutas)."] = "Vend au marchand tout ce qui va au marchand (pas ce qui va à l'HV ni ce que gardent vos parcours).",
  ["Sin escaneo de la AH: al vendedor solo se propone lo gris. Escanea para ver qué vale más en la AH.|r"] = "Pas d'analyse de l'HV : seuls les objets gris sont proposés au marchand. Analysez pour voir ce qui vaut plus à l'HV.|r",
