  -- Earn: minimum profit
  ["Beneficio mínimo"] = "Bénéfice minimum",
  ["No se proponen recetas que, con todas las fabricaciones que tocan, dejen menos que esto (tampoco materiales para vender que valgan menos)."] = "Les recettes qui rapportent moins que ça sur toutes leurs créations proposées ne sont pas proposées (ni les composants à vendre qui valent moins).",
  ["Arrastra o usa la rueda del ratón."] = "Faites-le glisser ou utilisez la molette.",
  ["Recetas que podrías aprender"] = "Recettes que vous pourriez apprendre",
  ["%s: no se propondrá venderlo. Se deshace con clic derecho en \"No se venden\" (pestaña Inventario)."] = "%s : ne sera plus proposé à la vente. Annulez avec un clic droit dans \"Pas à vendre\" (onglet Inventaire).",
  ["%s: vuelve a proponerse para vender."] = "%s : de nouveau proposé à la vente.",
  ["herramienta de profesión: no se vende"] = "outil de métier : pas vendu",
  ["lo marcaste para no venderlo"] = "vous l'avez marqué comme pas à vendre",
  ["clic derecho: volver a proponerlo"] = "clic droit : le proposer de nouveau",
  ["No se venden"] = "Pas à vendre",
  ["Herramienta de profesión: sin ella no puedes fabricar o recolectar. No se propone venderla."] = "Outil de métier : sans lui vous ne pouvez ni créer ni récolter, il n'est donc pas proposé à la vente.",
