  ["%s: se propondrá anunciarlo en la AH. Ctrl+clic derecho en su fila lo devuelve al vendedor."] = "%s : sera proposé à l'HV. Ctrl+clic droit sur sa ligne le renvoie au marchand.",
  ["%s: se propondrá venderlo al vendedor. Ctrl+clic derecho en su fila lo devuelve a la AH."] = "%s : sera proposé au marchand. Ctrl+clic droit sur sa ligne le renvoie à l'HV.",
  ["%s: vuelve a compararse con la AH."] = "%s : de nouveau comparé avec l'HV.",
  ["Para vender en la AH, de tus bolsas:"] = "À vendre à l'HV, depuis vos sacs :",
  ["Anuncias %d × %s · %d h"] = "Vous mettez en vente %d × %s · %d h",
  ["La Casa de Subastas no aceptó %s: %s"] = "L'hôtel des ventes n'a pas accepté %s : %s",
  ["para fabricar %s"] = "pour fabriquer %s",
