  ["Todas las recetas de cada profesión: cuántas tienes y dónde conseguir las demás."] = "Chaque recette de chaque métier : combien vous en avez et où obtenir les autres.",
  ["Escanear"] = "Analyser",
  ["Escanear la Casa de Subastas"] = "Analyser l'hôtel des ventes",
  ["Escaneo en curso."] = "Analyse en cours.",
  ["Abre la Casa de Subastas para poder escanearla."] = "Ouvrez l'hôtel des ventes pour pouvoir l'analyser.",
  ["Descarga todas las subastas y actualiza precios, rutas y alertas."] = "Télécharge toutes les enchères et met à jour les prix, les parcours et les alertes.",
  ["Todas las recetas que ofrece el juego en cada profesión: cuántas tienes y dónde conseguir las que faltan."] = "Chaque recette que le jeu propose dans chaque métier : combien vous en avez et où obtenir celles qui manquent.",
  ["Tienes %d de las %d recetas del juego."] = "Vous avez %d des %d recettes du jeu.",
  ["Este personaje no tiene la profesión."] = "Ce personnage n'a pas ce métier.",
  ["Pulsa para ver todas sus recetas y dónde se consiguen."] = "Cliquez pour voir toutes ses recettes et où les obtenir.",
  ["%s%d|r de %d recetas"] = "%s%d|r sur %d recettes",

  -- Waypoints
  ["Pide %s con %s (tienes %s)"] = "Requiert %s auprès de %s (vous êtes %s)",
  ["lugar desconocido"] = "lieu inconnu",
  ["%s está en %s."] = "%s est à %s.",
  ["Ruta marcada hacia %s, %s."] = "Itinéraire vers %s, %s défini.",
  ["Punto de ruta marcado hacia %s, %s."] = "Repère placé en %s, %s.",
  ["Instala Questie para ver dónde está y marcar el camino."] = "Installez Questie pour voir où c'est et tracer le chemin.",
  ["No se conoce ninguno de tu bando cerca (o está en otro continente)."] = "Aucun de votre faction connu à proximité (ou c'est sur un autre continent).",
  ["Clic: marcar el camino (mapa, minimapa y seguimiento)."] = "Clic : tracer le chemin (carte, minicarte et suivi).",
  ["Instala Questie para poder marcar el camino al instructor o al vendedor."] = "Installez Questie pour tracer le chemin vers le maître ou le marchand.",
  ["No se conoce ninguno de tu bando cerca."] = "Aucun de votre faction connu à proximité.",
  ["Usar los precios de Auctionator o TSM"] = "Utiliser les prix d'Auctionator ou de TSM",
  ["Si tu escaneo no tiene un objeto de tus bolsas, se usa el precio que guarda Auctionator o TSM para decidir si va a la AH o al vendedor. Tu escaneo siempre manda."] = "Si votre analyse n'a pas un objet de vos sacs, le prix enregistré par Auctionator ou TSM sert à décider s'il va à l'HV ou au marchand. Votre propre analyse a toujours la priorité.",
  ["Precio de %s (hace %d días): tu escaneo no tenía este objeto."] = "Prix %s (il y a %d jours) : votre analyse n'avait pas cet objet.",
  ["Precio de %s: tu escaneo no tenía este objeto."] = "Prix %s : votre analyse n'avait pas cet objet.",
  -- Assistant de parcours (Assistant.lua)
  ["¡Ruta completada!"] = "Parcours terminé !",
  ["Clic: ver lo que sacas vendiéndolo"] = "Clic : voir ce que rapporte la vente",
  ["Abre la ventana del addon para ver la ruta."] = "Ouvrez la fenêtre de l'addon pour voir le parcours.",
  ["Cerrar el asistente (vuelve con /cj mini)"] = "Fermer l'assistant (le rouvrir avec /cj mini)",
  ["Paso anterior"] = "Étape précédente",
  ["Paso siguiente"] = "Étape suivante",
  ["Solo para mirarlo: vuelve solo al paso actual."] = "Juste pour la consulter : revient tout seul à l'étape en cours.",
  ["No tienes ninguna ruta empezada: empieza una en la ventana del addon (botón Empezar ruta)."] = "Aucun parcours commencé : commencez-en un dans la fenêtre de l'addon (bouton Commencer le parcours).",
  ["esta tanda: %d"] = "ce lot : %d",
  ["sin materiales: sigue con el paso, se compran en la siguiente tanda"] = "pas de composants : continuez l'étape, ils s'achètent avec le lot suivant",
  ["Lo que llevas da para %d de las ~%d fabricaciones del paso. Con suerte te basta; si no, al acabarlo la ruta te llevará a comprar más."] = "Ce que vous avez couvre %d des ~%d fabrications de l'étape. Avec de la chance, cela suffit ; sinon, une fois épuisé, le parcours vous mènera en acheter plus.",
  -- Lignes d'achat du parcours (ProfessionUI.lua, AddBuyLines)
  ["Compra %d× %s"] = "Achetez %d× %s",
  ["Compra en la AH: %d materiales"] = "Acheter à l'HV : %d composants",
  ["Compra al vendedor: %d materiales"] = "Acheter au marchand : %d composants",
  ["en la AH"] = "à l'HV",
  ["en el vendedor"] = "chez le marchand",
  ["No había suficiente"] = "Il n'y en avait pas assez",
  ["comprar a este vendedor justo lo que falta"] = "acheter à ce marchand exactement ce qui manque",
  ["volver a añadirla a la Lista de compra y marcar el camino"] = "la remettre dans la liste de courses et indiquer le chemin",
  ["No está en tu Lista de compra · clic para añadirla"] = "Absente de votre liste de courses · clic pour l'ajouter",
  -- Novedades 0.58.0 (WhatsNew.lua)
  ["Opciones en su propia ventana"] = "Les options dans leur propre fenêtre",
  ["El engranaje junto al idioma abre las opciones, ordenadas por categorías: General y una por pestaña o ventana. Ya no están en el panel de AddOns del juego."] = "L'engrenage à côté du choix de langue ouvre les options, classées par catégorie : Général et une par onglet ou fenêtre. Elles ne sont plus dans le panneau AddOns du jeu.",
  ["Al vendedor, solo lo que no vale más en la AH"] = "Au marchand, seulement ce qui ne vaut pas plus à l'HV",
  ["Inventario y la ventana del vendedor ya no te proponen vender al vendedor lo que vale más en la AH. Si tu escaneo no tiene un objeto, se usa el precio de Auctionator o TSM."] = "L'inventaire et la fenêtre du marchand ne proposent plus de vendre au marchand ce qui vaut plus à l'HV. Si votre scan n'a pas un objet, le prix d'Auctionator ou de TSM est utilisé.",
  ["En el tope de tu rango, a entrenar"] = "Au maximum de votre rang, allez vous entraîner",
  ["Si llegas al tope de tu rango sin el siguiente, el paso actual de la ruta pasa a ser entrenarlo, en vez de fabricar algo que ya no sube puntos."] = "Si vous atteignez le maximum de votre rang sans le suivant, l'étape en cours du parcours devient l'entraîner, au lieu de fabriquer quelque chose qui ne rapporte plus de points.",
  ["La ruta explica su segunda receta"] = "Le parcours explique sa deuxième recette",
  ["Si hay otra receta más barata en oro y la ruta no la usa, el paso dice por qué: más fabricaciones, un paso más o aprenderla no compensa."] = "Si une autre recette est moins chère en or et que le parcours ne l'utilise pas, l'étape dit pourquoi : plus de fabrications, une étape de plus, ou l'apprendre ne vaut pas le coup.",
  ["Ya fuiste y no lo compraste todo: mientras puedas fabricar, la ruta sigue. Si no hay de dónde sacarlo, quita esa receta desde la ventana del addon."] = "Vous y êtes déjà allé sans tout acheter : tant que vous pouvez fabriquer, le parcours continue. S'il n'y a aucune source, retirez cette recette depuis la fenêtre de l'addon.",
  ["Stock limitado: venden pocas y reponen con el tiempo, y a veces otros jugadores las compran para revenderlas."] = "Stock limité : ils en vendent peu et se réapprovisionnent avec le temps, et d'autres joueurs les achètent parfois pour les revendre.",
  ["Sale mejor que la de la ruta."] = "Elle est meilleure que celle du parcours.",
  ["Asistente de la ruta"] = "Assistant de parcours",
  ["Sigue esta ruta paso a paso en un banner pequeño, sin la ventana del addon: qué toca, dónde ir y qué comprar. Clic otra vez para cerrarlo."] = "Suivez ce parcours étape par étape dans une petite bannière, sans la fenêtre de l'addon : quoi faire, où aller et quoi acheter. Cliquez à nouveau pour le fermer.",
  ["Aprende %s"] = "Apprenez %s",
  ["Aún no la tienes: apréndela en su instructor (Aprendiz, gratis o casi). Sube el tope a 75."] = "Vous ne l'avez pas encore : apprenez-le auprès de son maître (Apprenti, gratuit ou presque). Il monte le maximum à 75.",
  ["Solo puedes tener dos profesiones principales (las de recolección también cuentan): si ya tienes dos, tendrías que olvidar una."] = "Vous ne pouvez avoir que deux métiers principaux (ceux de récolte comptent aussi) : si vous en avez déjà deux, il faudrait en désapprendre un.",
  ["Instructor · aún no la tienes"] = "Maître · vous ne l'avez pas encore",
  ["Sube el tope a %d%s"] = "Monte le maximum à %d%s",
  -- Flecha GPS del asistente (Assistant.lua)
  ["%d yd"] = "%d yd",
  ["En otro continente"] = "Sur un autre continent",
  ["Sin posición aquí"] = "Pas de position ici",
  -- Banco del asistente (ProfessionUI.lua AddBuyLines, Assistant.lua)
  ["Saca %d× %s del banco"] = "Retirez %d× %s de la banque",
  ["Ve al banco: %d materiales"] = "Allez à la banque : %d composants",
  ["en el banco"] = "à la banque",
  ["sacar a tus bolsas lo que falta"] = "mettre ce qui manque dans vos sacs",
  ["Banquero más cercano"] = "Banquier le plus proche",
  ["Sacar del banco"] = "Retirer de la banque",
  ["saca %d (tienes %d en el banco)"] = "retirer %d (vous en avez %d à la banque)",
  ["Según lo que había la última vez que abriste el banco."] = "D'après ce qu'il y avait la dernière fois que vous avez ouvert la banque.",
  ["No cabe todo en tus bolsas: faltan %d por sacar del banco."] = "Tout ne tient pas dans vos sacs : encore %d à retirer de la banque.",
  [" o "] = " ou ",
  ["Está en %s"] = "C'est en %s",
  ["Barco en %s"] = "Bateau à %s",
  ["Zepelín en %s"] = "Zeppelin à %s",
  ["Asistente de ruta"] = "Assistant de parcours",
  ["Sacar el asistente al empezar una ruta"] = "Afficher l'assistant en commençant un parcours",
  ["Al empezar una ruta sale solo el asistente con ella. Desactivado, solo sale cuando lo abres: botón del catalejo junto a Dejar ruta, o /cj mini."] = "Quand vous commencez un parcours, l'assistant apparaît tout seul. Désactivé, il n'apparaît que si vous l'ouvrez : bouton longue-vue à côté de Quitter le parcours, ou /cj mini.",
  ["Bloquear el asistente"] = "Verrouiller l'assistant",
  ["No se mueve al arrastrarlo."] = "Il ne bouge pas quand on le fait glisser.",
  ["Mostrar la flecha GPS"] = "Afficher la flèche GPS",
  -- Confirmar antes de las acciones de golpe y novedades (UI.lua ES:Confirm, WhatsNew.lua)
  ["Ya no se mostrará este aviso. Se vuelve a activar en /cj opciones (%s)."] = "Cet avertissement ne s'affichera plus. Réactivez-le dans /cj options (%s).",
  ["No volver a mostrar este aviso"] = "Ne plus afficher cet avertissement",
  ["Se vuelve a activar en /cj opciones (%s)."] = "Réactivable dans /cj options (%s).",
  ["Sí"] = "Oui",
  ["No"] = "Non",
  ["Comprar todo"] = "Tout acheter",
  ["¿Comprar %d materiales de la lista de compra por %s?"] = "Acheter %d composants de la liste de courses pour %s ?",
  ["¿Vender %d objetos al vendedor por %s?"] = "Vendre %d objets au marchand pour %s ?",
  ["Confirmar antes de Vender todo"] = "Confirmer avant Tout vendre",
  ["Al pulsar Vender todo en la ventana junto al vendedor, pregunta antes qué vende y por cuánto."] = "En cliquant sur Tout vendre dans la fenêtre à côté du marchand, demande d'abord ce qui est vendu et pour combien.",
  ["Confirmar antes de Comprar todo"] = "Confirmer avant Tout acheter",
  ["Al pulsar Comprar todo en la ventana junto al vendedor, pregunta antes cuántos materiales compra y por cuánto."] = "En cliquant sur Tout acheter dans la fenêtre à côté du marchand, demande d'abord combien de composants sont achetés et pour combien.",
  ["Confirmar antes de vender todo al vendedor"] = "Confirmer avant de tout vendre au marchand",
  ["Al pulsar el botón de vender al vendedor de la pestaña Inventario, pregunta antes cuántos objetos vende y por cuánto."] = "En cliquant sur le bouton de vente au marchand de l'onglet Inventaire, demande d'abord combien d'objets sont vendus et pour combien.",
  ["Mostrar las novedades al actualizar"] = "Afficher les nouveautés après une mise à jour",
  ["Tras actualizar el addon, una ventana con lo nuevo de esa versión (una vez por versión). También se quita con su casilla \"No volver a mostrar\"."] = "Après une mise à jour de l'addon, une fenêtre avec les nouveautés de cette version (une fois par version). Désactivable aussi avec sa case \"Ne plus afficher\".",
  ["Ya no se mostrarán las novedades. Se vuelven a activar en /cj opciones (General)."] = "Les nouveautés ne s'afficheront plus. Réactivez-les dans /cj options (Général).",
  ["No volver a mostrar"] = "Ne plus afficher",
  ["Clic: seleccionarlo y marcarlo con una estrella (si está cerca)."] = "Clic : le cibler et le marquer d'une étoile (s'il est proche).",
  ["Controles siempre visibles"] = "Contrôles toujours visibles",
  ["Activado, los controles alrededor del asistente (flechas de pasos, modo de compra, saltar, cerrar) se ven siempre. Desactivado, se despliegan al pasar el ratón por el asistente y se pliegan al salir."] = "Activé, les contrôles autour de l'assistant (flèches d'étapes, mode d'achat, passer, fermer) sont toujours visibles. Désactivé, ils se déplient au survol de l'assistant et se replient quand vous le quittez.",
  ["Clic para marcarlo"] = "Clic pour le marquer",
  ["Encima del asistente, una flecha que te lleva al instructor o al vendedor del paso, con las yardas y el tiempo. Al pulsar el banner se marca además el camino como en la ventana del addon."] = "Au-dessus de l'assistant, une flèche qui vous mène au maître ou au marchand de l'étape, avec les yards et le temps. Cliquer sur la bannière indique aussi le chemin comme dans la fenêtre de l'addon.",
  ["Saltar"] = "Passer",
  ["ruta entera"] = "parcours entier",
  ["ya puedes · antes de %d"] = "possible dès maintenant · avant %d",
  ["aprende también: %s"] = "apprenez aussi : %s",
  ["Receta comprada: "] = "Recette achetée : ",
  ["Buzón"] = "Boîte aux lettres",
  ["+%d después"] = "+%d plus tard",
  ["Guarda las otras %d: no se sabe si se venden bien, así que anuncia unas pocas y, cuando se vendan, las siguientes (aunque sea en varios días). En la AH valen más que en el vendedor."] = "Gardez les %d autres : on ne sait pas s'ils se vendent bien, alors mettez-en quelques-uns en vente et, quand ils sont vendus, les suivants (même sur plusieurs jours). Ils valent plus à l'HV qu'au marchand.",
  ["Siguiendo el consejo (AH y vendedor)"] = "En suivant le conseil (HV et marchand)",
  ["Lo del vendedor es seguro; lo de la AH, si se vende"] = "La part marchand est sûre ; celle de l'HV, si elle se vend",
  ["con AH: "] = "avec HV : ",
  ["Vendiendo al vendedor (seguro)"] = "En vendant au marchand (sûr)",
  ["El segundo total cuenta lo que la vista %s aconseja anunciar en la AH a su precio actual. No es seguro: depende de que se venda, a ese precio y antes de que caduque la subasta. Lo del vendedor sí es seguro."] = "Le second total compte ce que la vue %s conseille de mettre à l'HV, à son prix actuel. Ce n'est pas garanti : il faut que ça se vende, à ce prix, avant que l'enchère expire. La part marchand est sûre.",
  ["Para seguir fabricando, compra más"] = "Pour continuer à fabriquer, achetez-en plus",
  ["Clic: aprenderlo en este instructor."] = "Clic : l'apprendre auprès de ce maître.",
  ["Este instructor no lo enseña (o aún no te llega el nivel)."] = "Ce maître ne l'enseigne pas (ou votre niveau ne suffit pas encore).",
  ["Buzón más cercano"] = "Boîte aux lettres la plus proche",
  ["Recoge el correo"] = "Récupérez votre courrier",
  ["Lo comprado en la AH: "] = "Acheté à l'HV : ",
  ["%d objetos comprados en la AH"] = "%d objets achetés à l'HV",
  ["Lo que compraste en la AH para esta ruta. Este paso se da por hecho cuando lo tienes en las bolsas."] = "Ce que vous avez acheté à l'HV pour ce parcours. Cette étape est faite quand c'est dans vos sacs.",
  ["Comprada en la AH · apréndela antes de fabricar"] = "Achetée à l'HV · apprenez-la avant de fabriquer",
  ["aprende %s primero"] = "apprenez d'abord %s",
  ["Compra detectada: %s ×%d. Cuenta ya para la ruta y la lista de compra."] = "Achat détecté : %s ×%d. Il compte déjà pour le parcours et la liste de courses.",
  ["compra también la receta: %s"] = "achetez aussi la recette : %s",
  ["fabrica aquí hasta %s"] = "fabriquez ici jusqu'à %s",
  ["Los pasos de compra y la Lista de compra piden solo lo del tramo en el que estás."] = "Les étapes d'achat et la liste de courses ne demandent que l'étape en cours.",
  ["Los pasos de compra y la Lista de compra piden lo que falta para toda la ruta, de una vez."] = "Les étapes d'achat et la liste de courses demandent tout ce qui manque pour le parcours, d'un coup.",
  ["Es el modo de ahora."] = "C'est le mode actuel.",
  ["Clic: cambiar a este modo."] = "Clic : passer à ce mode.",
  ["Cómo funciona el asistente"] = "Fonctionnement de l'assistant",
  ["Abrir la ruta en la ventana"] = "Ouvrir le parcours dans la fenêtre",
  ["La ruta entera, en el paso en el que estás: ahí puedes quitar una receta, cambiar las opciones de la ruta o dejarla."] = "Le parcours entier, à l'étape où vous en êtes : vous pouvez y retirer une recette, changer les options du parcours ou le quitter.",
  ["Clic: la explicación, paso a paso."] = "Clic : l'explication complète, étape par étape.",
  ["Te guía paso a paso por tu ruta empezada, sin abrir la ventana: enseña el mismo paso que la vista Ruta."] = "Il vous guide étape par étape dans votre parcours, sans ouvrir la fenêtre : il montre la même étape que la vue Parcours.",
  ["Bloquearlo o sacarlo solo al empezar una ruta: /cj opciones, Asistente de ruta."] = "Le verrouiller, ou ne l'afficher qu'au début d'un parcours : /cj options, Assistant de parcours.",
  ["Un clic en el banner hace lo que toca"] = "Un clic sur la bannière fait l'étape",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra; con el banco, saca a las bolsas justo lo que falta. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "HV ouvert, il achète le composant suivant ; chez un marchand, il lui achète ; à la banque, il met dans vos sacs juste ce qui manque. Sans rien d'ouvert, il vous mène au PNJ le plus proche. Il n'achète jamais sans votre clic.",
  ["El color dice qué toca"] = "La couleur indique l'étape",
  ["¿Por qué pide más fabricaciones de las que me dan los materiales?"] = "Pourquoi demande-t-il plus de fabrications que mes composants ne le permettent ?",
  ["La ruta compra por tandas: en las recetas amarillas y verdes no todas suben punto. \"Esta tanda: N\" es para cuántas te llega lo que llevas. Con suerte basta; si no, al acabarla te manda a comprar más."] = "Le parcours achète par lots : avec les recettes jaunes et vertes, toutes les fabrications ne font pas monter. \"Ce lot : N\" indique combien ce que vous avez permet. Avec de la chance cela suffit ; sinon, une fois épuisé, il vous envoie en acheter plus.",
  ["¿Qué significa el número de \"Fabrica N×\"?"] = "Que signifie le nombre dans \"Créer N×\" ?",
  ["Es lo que te falta de media para acabar el paso, según los puntos que te quedan. Baja con cada fabricación; si tienes mala suerte y el punto no sube, se queda quieto hasta que lo subas."] = "C'est le nombre de fabrications qu'il vous faut en moyenne pour finir l'étape, selon les points qui vous manquent. Il baisse à chaque fabrication ; si vous n'avez pas de chance et que le point ne monte pas, il reste fixe jusqu'à ce que vous l'obteniez.",
  ["Lo tengo de otro sitio (comercio, hermandad, otro personaje)"] = "Je l'ai eu ailleurs (canal commerce, guilde, autre personnage)",
  ["En el paso de compra, pulsa Saltar: lo da por comprado en este tramo. Lo comprado en la AH ya cuenta aunque siga en el correo."] = "Sur l'étape d'achat, cliquez sur Passer : il le compte comme acheté pour cette étape. Ce que vous achetez à l'HV compte déjà même s'il est encore dans le courrier.",
  ["¿Y si fabrico otra cosa o voy por otro orden?"] = "Et si je fabrique autre chose ou change d'ordre ?",
  ["La ruta mira tu nivel y tus bolsas, no lo que fabricaste: se pone al día sola. Si gastaste materiales, te mandará a comprar lo que falte."] = "Le parcours regarde votre niveau et vos sacs, pas ce que vous avez fabriqué : il se met à jour tout seul. Si vous avez utilisé des composants, il vous enverra acheter ce qui manque.",
  ["Comprar o ir al banco"] = "Acheter ou aller à la banque",
  ["Ir a un PNJ"] = "Aller voir un PNJ",
  ["La flecha te lleva al PNJ"] = "La flèche vous mène au PNJ",
  ["Sale cuando el paso tiene un PNJ: verde si vas bien, roja si vas al revés. También lo marca en el mapa y el minimapa. En otro continente te dice qué barco o zepelín tomar."] = "Elle apparaît quand l'étape a un PNJ : verte dans la bonne direction, rouge dans la mauvaise. Il est aussi marqué sur la carte et la minicarte. Sur un autre continent, elle vous dit quel bateau ou zeppelin prendre.",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "HV ouvert, il achète le composant suivant ; chez un marchand, il lui achète. Sans rien d'ouvert, il vous mène au PNJ le plus proche. Il n'achète jamais sans votre clic.",
  ["Comprar"] = "Acheter",
  ["Comprar: por tramos"] = "Acheter : par étape",
  ["Comprar: ruta entera"] = "Acheter : tout le parcours",
  ["Saltar este paso"] = "Passer cette étape",
  ["Recuperar"] = "Rétablir",
  ["Recuperar este paso"] = "Rétablir cette étape",
  ["Lo saltaste: vuelve a pedirte comprarlo."] = "Vous l'avez passée : elle vous redemande de l'acheter.",
  ["Si te equivocas, vuelve a él con la flecha de paso anterior y pulsa Recuperar."] = "En cas d'erreur, revenez-y avec la flèche de l'étape précédente et cliquez sur Rétablir.",
  ["Saltado · Recuperar lo vuelve a poner"] = "Passée · Rétablir la remet",
  ["Lo das por comprado y pasa al siguiente paso. Para lo que el addon no ve (el chat de comercio, el banco de hermandad, un alter). Solo en este tramo."] = "Le compte comme acheté et passe à l'étape suivante. Pour ce que l'addon ne voit pas (canal commerce, banque de guilde, un reroll). Seulement pour cette étape.",
  ["Lo comprado en la AH ya cuenta aunque siga en el correo."] = "Ce que vous achetez à l'HV compte déjà même s'il est encore dans le courrier.",
  ["Quitar de Ganar dinero"] = "Retirer de Gagner de l'or",
  ["No volver a proponer esta receta aquí: por ejemplo, si pide una estación que no tienes. Se recupera con la fila de recetas quitadas, al final de la lista."] = "Ne plus proposer cette recette ici : par exemple, si elle demande une station que vous n'avez pas. On la récupère avec la ligne des recettes retirées, en bas de la liste.",
  ["Recetas quitadas de Ganar dinero: %d"] = "Recettes retirées de Gagner de l'or : %d",
  ["Quitadas de Ganar dinero"] = "Retirées de Gagner de l'or",
  ["En las recetas verdes (y a veces en las amarillas) no todas las fabricaciones suben punto, así que la ruta compra por tandas: cuando gastas una, te trae a comprar la siguiente y luego vuelves a fabricar."] = "Avec les recettes vertes (et parfois jaunes), toutes les fabrications ne font pas monter, alors le parcours achète par lots : quand vous en terminez un, il vous amène acheter le suivant, puis vous reprenez la fabrication.",
  ["BETA"] = "BÊTA",
  ["Asistente de ruta (beta)"] = "Assistant de parcours (bêta)",
  ["Está en pruebas. Si ves algo raro, abre un post en el canal de bugs de nuestro Discord: el enlace está en el botón Informar de un error, arriba a la izquierda de la ventana del addon."] = "Il est en test. Si vous voyez quelque chose de bizarre, ouvrez un post dans le salon bugs de notre Discord : le lien se trouve derrière le bouton Signaler un bug, en haut à gauche de la fenêtre de l'addon.",
  ["Si no quieres usarlo, desactívalo en /cj opciones, Asistente de ruta."] = "Si vous ne voulez pas l'utiliser, désactivez-le dans /cj options, Assistant de parcours.",
  ["los %d que hacen falta"] = "les %d nécessaires",
  ["%d en total · tienes %d"] = "%d au total · vous en avez %d",
  ["%d en total"] = "%d au total",
  ["Demanda (TSM, región): ~%s vendidos al día, tasa de venta %s"] = "Demande (TSM, région) : ~%s vendus par jour, taux de vente %s",
  ["Demanda (TSM): sin datos de este objeto (¿la app de TSM está al día?)"] = "Demande (TSM) : pas de données pour cet objet (l'application TSM est-elle à jour ?)",
  ["TSM: en la región se vende de media a %s, bastante menos que los %s con los que se cuenta aquí."] = "TSM : dans la région, il se vend en moyenne %s, bien moins que les %s utilisés ici.",
  ["Poca demanda según TSM y otra alerta en contra: aunque el margen parezca bueno, probablemente no lo venderás."] = "Faible demande selon TSM et un autre signal d'alerte : même si la marge semble bonne, vous ne le vendrez probablement pas.",
  ["TSM: en la región se venden ~%s al día: como mucho lo que se vende en %d días."] = "TSM : ~%s vendus par jour dans la région : au maximum ce qui se vend en %d jours.",
  ["Usar la demanda de TSM"] = "Utiliser la demande de TSM",
  ["Si tienes TSM con su app de escritorio: cuántos se venden al día en la región y qué parte de lo que se anuncia se vende. Es una alerta más de mercado y no se proponen más de los que se venden en 2 días. Tus escaneos siguen mandando."] = "Si vous avez TSM avec son application de bureau : combien se vendent par jour dans la région et quelle part des enchères se vend. C'est un signal d'alerte de plus et on ne propose jamais plus que ce qui se vend en 2 jours. Vos propres scans restent prioritaires.",
  ["receta con enfriamiento, una cada vez."] = "recette avec temps de recharge, une à la fois.",
  ["No se sabe aún si su enfriamiento está listo: al abrir la profesión se comprueba (si no lo está, sale del lote)."] = "On ne sait pas encore si son temps de recharge est prêt : c'est vérifié à l'ouverture du métier (sinon, elle sort du lot).",
  [" · enfriamiento: ¿listo?"] = " · recharge : prête ?",
  [" · enfriamiento listo"] = " · recharge prête",
  ["Abre la profesión para saber si está listo"] = "Ouvrez le métier pour savoir si elle est prête",
  ["Listo: está en el lote de hoy"] = "Prête : elle est dans le lot du jour",
  ["Demanda de TSM: vendidos al día, mínimo"] = "Demande TSM : vendus par jour, minimum",
  ["Por debajo, alerta de poca demanda (y no se propone aprender la receta). Cuenta toda la región: tu reino vende como mucho eso."] = "En dessous, une alerte de faible demande (et on ne propose pas d'apprendre la recette). Compte toute la région : votre royaume en vend au plus autant.",
  ["Demanda de TSM: tasa de venta mínima"] = "Demande TSM : taux de vente minimum",
  ["Qué parte de lo que se anuncia acaba vendiéndose (1 = todo). Por debajo, alerta de poca demanda."] = "Quelle part des enchères finit par se vendre (1 = toutes). En dessous, une alerte de faible demande.",
  ["%s al día"] = "%s par jour",
  ["No cuenta"] = "Désactivé",
  ["Tiene enfriamiento (una cada vez): lo que cuesta aprenderla se recupera en %d fabricaciones."] = "A un temps de recharge (une à la fois) : ce que coûte l'apprendre est remboursé en %d fabrications.",
  ["Tiene enfriamiento: se puede fabricar una cada vez."] = "A un temps de recharge : vous pouvez en fabriquer une à la fois.",
  [" · con enfriamiento"] = " · avec temps de recharge",
  ["Este vendedor no tiene: %s. Sigue la fila para ir a otro."] = "Ce marchand n'a pas : %s. Suivez la ligne pour aller chez un autre.",
  ["Nuevo: asistente de ruta (beta)"] = "Nouveau : assistant de parcours (bêta)",
  ["Con una ruta empezada, un banner pequeño te dice qué toca: fabricar, comprar en la AH o al vendedor, recoger el correo o entrenar. Un clic lo hace o te lleva. Se abre con el botón junto a Dejar ruta o con /cj mini."] = "Avec un parcours commencé, une petite bannière vous dit quoi faire : fabriquer, acheter à l'HV ou chez un marchand, relever le courrier ou vous entraîner. Un clic le fait ou vous y emmène. Ouvrez-le avec le bouton à côté de Quitter le parcours ou avec /cj mini.",
  ["Cuánto se tarda en fabricar"] = "Le temps de fabrication",
  ["Cada paso de la ruta dice cuánto tardas en fabricarlo, y la franja de arriba el tiempo de toda la ruta."] = "Chaque étape du parcours indique combien de temps prend sa fabrication, et la barre du haut le temps du parcours entier.",
  ["Lo que sacas vendiendo en la AH"] = "Ce que vous gagnez à l'HV",
  ["Bajo el total de la ruta, \"con AH\" dice lo que te quedaría si vendes lo fabricado como aconseja la vista Profit, en la AH y al vendedor."] = "Sous le total du parcours, \"avec HV\" indique ce qu'il vous resterait en vendant ce que vous fabriquez comme le conseille la vue Profit, à l'HV et au marchand.",
  ["Menos verdes en las rutas"] = "Moins de vert dans les parcours",
  ["La ruta prefiere recetas seguras a tramos largos en verde: menos fabricaciones y menos viajes a comprar, por muy poco oro más."] = "Le parcours préfère des recettes sûres aux longues étapes vertes : moins de fabrications et moins d'allers-retours pour acheter, pour très peu d'or en plus.",
  ["Vender, más fácil"] = "Vendre, plus simple",
  ["Vender todo vende todo de un clic, y lo que no tiene un precio fiable en la AH va al vendedor. Con Ctrl+clic derecho en una fila lo pasas de la AH al vendedor o al revés."] = "Tout vendre vend tout en un clic, et ce qui n'a pas de prix fiable à l'HV va au marchand. Ctrl+clic droit sur une ligne pour le passer de l'HV au marchand ou l'inverse.",
  ["Compras por tandas en verde"] = "Achats par lots pour les recettes vertes",
  ["En las recetas verdes compra por tandas, con algo de margen, y \"esta tanda: N\" dice para cuántas te llega lo que llevas. El tamaño de la tanda se cambia en /cj opciones, Lista de compra."] = "Pour les recettes vertes, il achète par lots, avec un peu de marge, et \"ce lot : N\" indique pour combien de fabrications ce que vous avez suffit. Changez la taille des lots dans /cj options, Liste de courses.",
  ["Enfriamientos en el lote de hoy"] = "Temps de recharge dans le lot du jour",
  ["Las transmutaciones y la Mooncloth que tienes listas entran en el Lote de hoy, una cada vez, y vuelven solas cuando están otra vez listas. También salen en las recetas que podrías aprender."] = "Les transmutations et l'étoffe lunaire prêtes entrent dans le Lot du jour, une à la fois, et reviennent toutes seules quand elles sont de nouveau prêtes. Elles apparaissent aussi dans les recettes que vous pourriez apprendre.",
  ["Confirmar antes de vender o comprar todo"] = "Confirmer avant de tout vendre ou tout acheter",
  ["Vender todo, Comprar todo y vender al vendedor desde el Inventario preguntan antes. Cada aviso se quita con \"No volver a mostrar\" y se vuelve a activar en las opciones."] = "Tout vendre, Tout acheter et la vente au marchand depuis l'Inventaire demandent d'abord. Chaque message se désactive avec \"Ne plus afficher\" et se réactive dans les options.",
  ["Quita recetas de Ganar dinero"] = "Retirer des recettes de Gagner de l'or",
  ["Con la X de una fila, Ganar dinero deja de proponerte esa receta (por ejemplo, si pide una estación que no tienes). Se recupera con la fila del final de la lista."] = "Avec le X d'une ligne, Gagner de l'or ne propose plus cette recette (par exemple, si elle demande un atelier que vous n'avez pas). Elle se récupère avec la ligne en bas de la liste.",
  ["Demanda de TSM"] = "Demande TSM",
  ["Si tienes TSM con su app, Ganar dinero tiene en cuenta cuántas se venden al día en tu región y no te propone fabricar más de lo que se vende. Los mínimos se ajustan en las opciones de Ganar dinero."] = "Si vous avez TSM avec son application, Gagner de l'or tient compte du nombre vendu par jour dans votre région et ne propose jamais de fabriquer plus que ce qui se vend. Les minimums se règlent dans les options de Gagner de l'or.",
  ["La bolsa de componentes cuenta"] = "Le sac de composants compte",
  ["Lo que llevas en la bolsa de componentes cuenta en la ruta, el Inventario y Ganar dinero, y \"Recoge el correo\" se completa aunque lo recogido vaya a esa bolsa."] = "Ce que vous avez dans le sac de composants compte dans le parcours, l'Inventaire et Gagner de l'or, et \"Récupérez votre courrier\" se valide même si ce que vous récupérez va dans ce sac.",
  ["Recetas con dos herramientas"] = "Recettes à deux outils",
  ["Los cascos de ingeniería piden el Blacksmith Hammer y la Arclight Spanner, y la ruta ya pide las dos."] = "Les casques d'ingénierie demandent le Marteau de forgeron et la Clé plate, et le parcours demande désormais les deux.",
  ["Gasta lo que sobra"] = "Utiliser les restes",
  ["Al acabar un paso, si te sobran materiales y fabricar con ellos deja más que venderlos, la ruta te lo propone."] = "À la fin d'une étape, s'il vous reste des matériaux et que fabriquer avec rapporte plus que les vendre, le parcours vous le propose.",
  ["Recetas de lo intermedio"] = "Recettes des produits intermédiaires",
  ["Si algo intermedio pide una receta que no sabes (Stonescale Oil), la ruta tiene una fila para aprenderla y cuenta su precio."] = "Si un produit intermédiaire demande une recette que vous ne connaissez pas (Huile de pierre-écaille), le parcours a une ligne pour l'apprendre et compte son prix.",
  ["Confirmar al anunciar, más fiable"] = "Confirmation de mise en vente plus fiable",
  ["El Sí anuncia antes de cerrar el aviso, el aviso se cierra al cerrar la AH o el vendedor, y ya no dice \"Anunciados\" si la AH no responde."] = "Oui met en vente avant de fermer le message, le message se ferme avec l'HV ou le marchand, et il ne dit plus \"mis en vente\" quand l'HV ne répond pas.",
  ["Rutas que no se quedan en el 99%"] = "Les parcours ne restent plus bloqués à 99 %",
  ["Si el cálculo de una ruta falla, la página lo dice en vez de quedarse en \"Calculando la ruta… 99%\". E Ingeniería 1-300 vuelve a calcularse rápido."] = "Si le calcul d'un parcours échoue, la page le dit au lieu de rester sur \"Calcul du parcours… 99%\". Et Ingénierie 1-300 se calcule de nouveau rapidement.",
  ["Herramientas en la lista de la compra"] = "Outils sur la liste de courses",
  ["Si un paso pide una herramienta que no llevas (Arclight Spanner), va a la lista de la compra en vez de darla por hecha."] = "Si une étape demande un outil que vous n'avez pas (Clé plate), il va sur la liste de courses au lieu d'être considéré comme acquis.",
  ["Transmutaciones en otros idiomas"] = "Transmutations dans d'autres langues",
  ["Con el juego en español, alemán o francés, la ruta ya no pide 186 transmutaciones seguidas: reconoce su enfriamiento."] = "Avec le jeu en espagnol, allemand ou français, le parcours ne demande plus 186 transmutations d'affilée : il reconnaît leur temps de recharge.",
  ["Sin errores en mazmorras"] = "Plus d'erreurs en donjon",
  ["Las compras de la AH se leen del chat solo con la AH abierta: en mazmorras y en combate ya no salen errores."] = "Les achats à l'HV ne sont lus dans le chat que lorsque l'HV est ouvert : plus d'erreurs en donjon ni en combat.",
  -- Investments tab (InvestUI.lua, Invest.lua)
  ["Inversiones"] = "Investissements",
  ["Precio al apuntar una compra o venta"] = "Prix en notant un achat ou une vente",
  ["Lo que escribes en el precio: el total (lo que pagaste por todo) o el precio por unidad. En la ventana de compra o venta lo puedes cambiar cada vez."] = "Ce que tu saisis comme prix : le total (ce que tu as payé pour le tout) ou le prix à l'unité. Tu peux le changer à chaque fois dans la fenêtre d'achat ou de vente.",
  ["Último escaneo (%s): nada a este precio; lo más barato, %s"] = "Dernière analyse (%s) : rien à ce prix ; le moins cher, %s",
  ["Último escaneo (%s): %s u a este precio o menos"] = "Dernière analyse (%s) : %s à ce prix ou moins",
  [" · el resto desde %s"] = " · le reste à partir de %s",
  ["Farmeado"] = "Farmé",
  ["Nueva pestaña: Inversiones"] = "Nouvel onglet : Investissements",
  ["Apunta lo que compras para revender (cantidad y precio, por unidad o total) y te dice tu precio medio y cuánto ganas o pierdes, neto de la comisión de la AH (5%)."] = "Note ce que tu achètes pour revendre (quantité et prix, à l'unité ou au total) et il t'indique ton prix moyen et combien tu gagnes ou perds, net de la commission de l'HV (5%).",
  ["hoy"] = "aujourd'hui",
  ["ayer"] = "hier",
  ["Escribe la cantidad y el precio (por ejemplo 2.5 = 2s 50c, o 1g 20s). Si lo has farmeado, 0."] = "Saisis la quantité et le prix (par exemple 2.5 = 2s 50c, ou 1g 20s). Si tu l'as farmé, 0.",
  ["Solo tienes %d para vender."] = "Tu n'en as que %d à vendre.",
