  ["Lista"] = "Liste",
  ["Fichas"] = "Fiches",
  ["Una fila por objeto: muchas de un vistazo, con menos scroll."] = "Une ligne par objet : beaucoup d'un coup d'œil, avec moins de défilement.",
  ["Dos por fila, con más detalle."] = "Deux par ligne, avec plus de détails.",
  ["Objeto"] = "Objet",
  ["Tienes"] = "Tu as",
  ["Tu cartera está vacía. Añade una compra: escribe el nombre del objeto en el buscador de arriba a la derecha."] = "Ton portefeuille est vide. Ajoute un achat : saisis le nom de l'objet dans la recherche en haut à droite.",
  ["Clic: ordenar por esta columna (otro clic: al revés)."] = "Clic : trier par cette colonne (autre clic : inverser).",
  ["Precio de %s: puede haber cambiado."] = "Prix de %s : il a pu changer.",
  ["Tu precio medio y lo que ganas con cada objeto."] = "Ton prix moyen et ce que tu gagnes sur chaque objet.",
  ["%d sin precio: no cuentan en Vale hoy."] = "%d sans prix : non comptés dans Vaut aujourd'hui.",
  ["Tu cartera de inversiones en la AH: lo que compraste, a qué precio medio y cuánto ganas o pierdes con cada objeto."] = "Ton portefeuille d'investissements à l'HV : ce que tu as acheté, à quel prix moyen, et combien tu gagnes ou perds sur chaque objet.",
  -- Options: Tabs category (order and hide the main window's tabs)
  ["Pestañas"] = "Onglets",
  ["Ocultar"] = "Masquer",
  ["OCULTA"] = "MASQUÉ",
  ["Clic: volver a mostrarla."] = "Clic : le réafficher.",
  ["Clic: ocultarla."] = "Clic : le masquer.",
  ["Columnas de la lista"] = "Colonnes de la liste",
  ["Clic en una columna para ocultarla de la vista de lista (o volver a mostrarla). El nombre del objeto gana el sitio."] = "Clic sur une colonne pour la masquer de la vue en liste (ou la réafficher). Le nom de l'objet prend la place.",
  ["Arrastra la fila para cambiar el orden. La de arriba es la que se abre al abrir el addon."] = "Fais glisser la ligne pour changer l'ordre. L'addon s'ouvre sur celui du haut.",
  ["Vuelve a poder ordenar las pestañas."] = "Revenir au tri des onglets.",
  ["Elige qué pestañas no se ven: clic en cada una y luego Hecho. Su página sigue abriéndose desde la AH o el asistente de ruta."] = "Choisis les onglets masqués : clic sur chacun, puis Terminé. Leur page s'ouvre toujours depuis l'HV ou l'assistant de parcours.",
  ["Tiene que quedar al menos una pestaña visible."] = "Au moins un onglet doit rester visible.",
  ["Lista de compra oculta: ya no tiene pestaña ni brilla al añadirle algo. La lista junto a la Casa de Subastas y la ventana del vendedor siguen igual."] = "Liste de courses masquée : elle n'a plus d'onglet et ne brille plus quand on y ajoute quelque chose. La liste à côté de l'hôtel des ventes et la fenêtre du marchand fonctionnent comme avant.",
  ["Ordena y oculta las pestañas"] = "Trier et masquer les onglets",
  ["En opciones, Pestañas: arrastra las pestañas para ordenarlas y oculta las que no uses. El addon se abre en la de arriba."] = "Dans les options, Onglets : fais glisser les onglets pour les trier et masque ceux que tu n'utilises pas. L'addon s'ouvre sur celui du haut.",
  ["Sin precio: instala Auctionator"] = "Pas de prix : installe Auctionator",
  ["No volver a mostrar este consejo"] = "Ne plus afficher ce conseil",
  ["Precios de tus últimos escaneos. Instala Auctionator para volver a escanear y tener el historial de precios."] = "Prix de tes dernières analyses. Installe Auctionator pour analyser à nouveau et avoir l'historique des prix.",
  ["Sin precios de este objeto. Instala Auctionator para escanear la AH y ver su evolución."] = "Pas de prix pour cet objet. Installe Auctionator pour analyser l'HV et voir son évolution.",
  ["Del historial de Auctionator"] = "De l'historique d'Auctionator",
  ["De tu escaneo de %s"] = "De ton scan : %s",
  ["De tu escaneo"] = "De ton scan",
  ["Subida sin confirmar: más del triple que el día anterior. No cuenta hasta que se repita otro día."] = "Hausse non confirmée : plus du triple de la veille. Elle ne compte pas tant qu'elle ne se répète pas un autre jour.",
  ["Día dudoso: mucho más caro que el día de antes y el de después. No cuenta."] = "Jour douteux : bien plus cher que la veille et le lendemain. Il ne compte pas.",
  ["Subida sin confirmar a %s: no cuenta hasta que se repita otro día."] = "Hausse non confirmée à %s : elle ne compte pas tant qu'elle ne se répète pas un autre jour.",
  ["Sin precio: búscalo en Auctionator"] = "Pas de prix : cherche-le dans Auctionator",
  ["Auctionator aún no tiene precios de este objeto: búscalo o escanea con Auctionator."] = "Auctionator n'a pas encore de prix pour cet objet : cherche-le ou scanne avec Auctionator.",
  ["Auctionator aún no deja otro escaneo completo: espera a que acabe su cuenta atrás."] = "Auctionator n'autorise pas encore un autre scan complet : attends la fin de son compte à rebours.",
  ["Instala Auctionator para escanear la AH: el addon lee su escaneo completo."] = "Installez Auctionator pour analyser l'HV : l'addon lit son analyse complète.",
  ["Auctionator aún no está listo para escanear: espera un momento o vuelve a abrir la AH."] = "Auctionator n'est pas encore prêt à analyser : attendez un instant ou rouvrez l'HV.",
  [" (con el escaneo de Auctionator)"] = " (avec le scan d'Auctionator)",
  ["Escaneando con Auctionator... %d s"] = "Scan avec Auctionator... %d s",
  ["Con Auctionator: el escaneo lo hace Auctionator (así guarda su historial de precios) y el addon lee esos mismos datos para todas las pestañas."] = "Avec Auctionator : c'est Auctionator qui scanne (il garde ainsi son historique des prix) et l'addon lit ces mêmes données pour tous les onglets.",
  ["Auctionator ha hecho un escaneo en modo resumen, que Crafter's Journal no usa (solo trae el precio mínimo de cada objeto). Para actualizar el addon, pulsa Escanear en Crafter's Journal, o activa en las opciones de Auctionator «%s»."] = "Auctionator a fait un scan en mode résumé, que Crafter's Journal n'utilise pas (il ne contient que le prix le plus bas de chaque objet). Pour mettre à jour l'addon, cliquez sur Analyser dans Crafter's Journal, ou activez « %s » dans les options d'Auctionator.",
  ["Auctionator está en modo resumen: su botón Escanear no actualiza Crafter's Journal. Usa este botón, o activa en las opciones de Auctionator «%s»."] = "Auctionator est en mode résumé : son bouton Scanner ne met pas à jour Crafter's Journal. Utilisez ce bouton, ou activez « %s » dans les options d'Auctionator.",
  ["Precios del historial de Auctionator: se ponen al día cada vez que escaneas."] = "Prix de l'historique d'Auctionator : ils se mettent à jour à chaque scan.",
  ["Mayús+clic: buscarlo en la AH"] = "Maj+clic : le chercher à l'HV",
  ["Minería"] = "Minage",
  ["con %s"] = "avec %s",
  ["neto %s"] = "net %s",
  ["ganas %s"] = "vous gagnez %s",
  ["Cuenta del paso:"] = "Le calcul de cette étape :",
  ["Se recupera vendiéndolo"] = "Récupéré en le vendant",
  ["Se recupera (vendido o guardado)"] = "Récupéré (vendu ou gardé)",
  ["Aprender la receta va en su propia fila."] = "Apprendre la recette est sur sa propre ligne.",
  ["Cómo elige la ruta"] = "Comment l'itinéraire est choisi",
  ["De media hacen falta %d y se piden %d (%d de margen), por si los puntos tardan en subir. Si te sobran, sirven para el tramo siguiente."] = "En moyenne il en faut %d et %d sont demandés (%d de marge), au cas où les points tardent. S'il en reste, ils servent à l'étape suivante.",
  ["La ruta busca la forma más barata de subir contando lo que recuperas: los materiales a precio de la AH (o del vendedor, si sale más barato) menos lo que sacas vendiendo al vendedor lo que fabricas, más el instructor. Por eso a veces elige una receta con materiales más caros: se vende mejor o hacen falta menos fabricaciones. Las guías suelen mirar solo los materiales, así que la ruta puede no coincidir con ellas."] = "L'itinéraire cherche la façon la moins chère de monter en comptant ce que vous récupérez : les composants au prix de l'HV (ou du marchand, s'il est moins cher) moins ce que vous tirez de la vente au marchand de ce que vous fabriquez, plus l'entraîneur. C'est pourquoi il choisit parfois une recette aux composants plus chers : elle se revend mieux ou demande moins de créations. Les guides ne regardent souvent que les composants, donc l'itinéraire peut ne pas leur correspondre.",
}
